125	func (s *Store) UpdateAttachment(ctx context.Context, update *UpdateAttachment) error {
126		if update.UID != nil && !base.UIDMatcher.MatchString(*update.UID) {
127			return errors.New("invalid uid")
128		}
129		return s.driver.UpdateAttachment(ctx, update)
130	}
